android.extraProguardRules:
# Android clasifica escribir datos sensibles en el log del sistema como
# vulnerabilidad (MASVS-STORAGE), y esta es la mitigación que su propia
# documentación recomienda. Hace falta porque expo-speech-recognition
# escribe la transcripción Y las pistas de vocabulario (las insulinas de
# la usuaria y su catálogo) con Log.d, sin condición.
#
# No basta con que el log sea privado de la app: Android advierte que en
# muchos aparatos vienen apps de fábrica con permiso READ_LOGS.
#
# `-assumenosideeffects` solo aplica en release. En debug el log sigue.
-assumenosideeffects class android.util.Log {
  public static int v(...);
  public static int d(...);
  public static int i(...);
}
